from funcy import memoize, cache, reraise
from funcy.calc import SkipMemoization
from functools import partial

for decorator in (memoize, memoize(), cache(60)):
    calls = []
    @decorator
    def f(*args, **kwargs):
        calls.append((args, kwargs))
        return len(calls)
    memory = f.memory
    assert f.skip is SkipMemoization
    assert f(1, b=2, a=3) == f(1, a=3, b=2) == 1
    assert f(2) == 2
    f.invalidate(1, a=3, b=2)
    f.invalidate(1, b=2, a=3)
    assert f(2) == 2
    assert f(1, b=2, a=3) == 3
    f.invalidate_all()
    assert f.memory is memory and memory == {}
    assert f(2) == 4

for decorator in (memoize(key_func=lambda x: len(x)), cache(60, key_func=len)):
    @decorator
    def f(x):
        return x
    assert f('a') == f('b') == 'a'
    f.invalidate('c')
    assert f('b') == 'b'

for decorator in (memoize, cache(60)):
    for args in ((), ('not cached',)):
        @decorator
        def f():
            raise f.skip(*args)
        assert f() == (args[0] if args else None)
        assert f.memory == {}

original = ValueError('original')
instance = RuntimeError('fixed')
class CallableError(RuntimeError):
    def __call__(self, exc):
        raise AssertionError('exception instances must not be invoked')

class Transform:
    def __call__(self, exc):
        assert exc is original
        return RuntimeError('mapped: ' + str(exc))

for into in (RuntimeError, instance, CallableError(), Transform(),
             lambda exc: RuntimeError(str(exc)), partial(lambda prefix, exc: RuntimeError(prefix + str(exc)), 'mapped: ')):
    try:
        with reraise(ValueError, into):
            raise original
    except RuntimeError as result:
        assert result.__cause__ is original
        if isinstance(into, BaseException):
            assert result is into
        if into is RuntimeError:
            assert result.args == ()
    else:
        raise AssertionError('not reraised')

@reraise(ValueError, lambda exc: RuntimeError(str(exc)))
def decorated(value):
    if value:
        raise original
    return 42
assert decorated(False) == 42
for _ in range(2):
    try:
        decorated(True)
    except RuntimeError as result:
        assert result.__cause__ is original
    else:
        raise AssertionError('not reraised')
print('Focused API checks passed')
